// Totals values by key and answers queries.
//
// Input file: records ("<key> <value>") then one empty line, then query keys.
// The file is handled as raw bytes: each byte becomes one char (latin1), so two
// keys match exactly when their bytes match, and output reproduces the bytes.

const MIN = -(2n ** 63n);
const MAX = 2n ** 63n - 1n;

interface Total {
  sum: bigint;
  overflow: boolean;
}

const CHUNK = 0x8000;

function bytesToLatin1(bytes: Uint8Array): string {
  const parts: string[] = [];
  for (let i = 0; i < bytes.length; i += CHUNK) {
    parts.push(String.fromCharCode(...bytes.subarray(i, i + CHUNK)));
  }
  return parts.join("");
}

function latin1ToBytes(text: string): Uint8Array {
  const bytes = new Uint8Array(text.length);
  for (let i = 0; i < text.length; i++) {
    bytes[i] = text.charCodeAt(i);
  }
  return bytes;
}

function stripCR(line: string): string {
  return line.endsWith("\r") ? line.slice(0, -1) : line;
}

function answer(text: string): string {
  const lines = text.split("\n");
  const totals = new Map<string, Total>();

  // First section: records, until the first empty line.
  let i = 0;
  for (; i < lines.length; i++) {
    const line = stripCR(lines[i]);
    if (line === "") break;
    const space = line.indexOf(" ");
    if (space <= 0) continue;
    const key = line.slice(0, space);
    const value = BigInt(line.slice(space + 1).trim());

    let total = totals.get(key);
    if (total === undefined) {
      total = { sum: 0n, overflow: false };
      totals.set(key, total);
    }
    if (total.overflow) continue;
    total.sum += value;
    if (total.sum < MIN || total.sum > MAX) {
      total.overflow = true;
    }
  }

  // Second section: one query key per line.
  const out: string[] = [];
  for (i++; i < lines.length; i++) {
    const key = stripCR(lines[i]);
    if (key === "") continue;
    const total = totals.get(key);
    if (total === undefined) {
      out.push(`${key}=absent`);
    } else if (total.overflow) {
      out.push(`${key}=overflow`);
    } else {
      out.push(`${key}=${total.sum}`);
    }
  }

  return out.map((line) => line + "\n").join("");
}

async function writeAll(bytes: Uint8Array): Promise<void> {
  let written = 0;
  while (written < bytes.length) {
    written += await Deno.stdout.write(bytes.subarray(written));
  }
}

if (import.meta.main) {
  const path = Deno.args[0];
  if (path === undefined) {
    console.error("usage: main.ts <file>");
    Deno.exit(2);
  }
  const bytes = await Deno.readFile(path);
  const output = answer(bytesToLatin1(bytes));
  if (output.length > 0) {
    await writeAll(latin1ToBytes(output));
  }
}

